function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function save(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('Changes could not be saved in this browser.');return false}}
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',3000)}
function modal(title,body){document.getElementById('dialogContent').innerHTML=`<h2>${escapeHTML(title)}</h2>${body}`;document.getElementById('dialog').showModal()}
document.getElementById('closeDialog').onclick=()=>document.getElementById('dialog').close();
function notifications(){modal('Your learning reminders','<p>Your weekly learning goal is within reach. You have 3 pending roadmap targets.</p><p>Sample reminders from your demo workspace. Task changes are saved on this device.</p>')}
function activityRows(all=false){return `<div class="activity-list">${activities.slice(0,all?5:3).map((a,i)=>`<button class="activity" onclick="openDomain(${a.domain})"><span class="status-icon ${a.type}"></span><span class="activity-text"><strong>${a.title}</strong><p>${a.description}</p><span class="tag">${domains[a.domain].name}</span></span><span class="timestamp">${a.time}</span></button>`).join('')}</div>`}
function basehome(){header.className='';header.innerHTML=`${renderGreeting()}<div class="hero"><div class="eyebrow">YOUR PERSONAL LEARNING SPACE</div><h1>ZETA</h1><p>KNOWLEDGE & PROJECT ENGINE</p></div><div class="metrics"><div class="metric"><div class="metric-top">${icon('trend')}<span>+2</span></div><b>12</b><p>Active Projects</p><small>This week</small></div><div class="metric"><div class="metric-top">${icon('analytics')}<span>↗</span></div><b>48</b><p>Studies Logged</p><small>This month</small></div><div class="metric"><div class="metric-top">${icon('file')}<span>+5</span></div><b>156</b><p>Stored Assets</p><small>PDFs & links</small></div></div>`;main.innerHTML=`<section class="quick"><div class="section-heading"><h2>Quick Access</h2><span class="pill">8 domains</span></div>${domainGrid()}</section><section class="section"><div class="section-heading"><h2>Recent Activity</h2><button class="text-button" onclick="navigate('activity')">See all ${icon('arrow')}</button></div>${activityRows()}</section><p class="footer-note">A LITTLE PROGRESS. EVERY DAY.</p><p class="subtitle" style="text-align:center;font-size:9px">Demo workspace · Sample metrics and learning content</p>`}
function updateTask(id,val){tasks[id]=val;save('nexus-tasks',tasks);learningUpdates.unshift({domain:Number(id.split('-')[0]),task:Number(id.split('-')[1]),completed:val,time:new Date().toISOString()});learningUpdates=learningUpdates.slice(0,100);save('zeta-learning-updates',learningUpdates);if(page==='domain'){const domainId=id.split('-')[0];const progress=Math.round([0,1,2].filter(i=>tasks[`${domainId}-${i}`]).length/3*100);const ring=main.querySelector('.ring');if(ring){ring.style.setProperty('--progress',progress+'%');ring.innerHTML=`<span>${progress}%<small>tasks complete</small></span>`}const updates=main.querySelector('#localUpdates');if(updates)updates.innerHTML=localUpdatesHTML(Number(domainId))}toast(val?'Target completed. Keep it up.':'Target marked as pending.')}
function snippet(d){const snippets=[
'# Train a baseline classifier\nfrom sklearn.linear_model import LogisticRegression\nmodel = LogisticRegression(max_iter=500)\nmodel.fit(X_train, y_train)\nprint(model.score(X_test, y_test))',
'# Binary search: O(log n)\ndef search(items, target):\n    low, high = 0, len(items) - 1\n    while low <= high:\n        mid = (low + high) // 2\n        if items[mid] == target: return mid\n        if items[mid] < target: low = mid + 1\n        else: high = mid - 1\n    return -1',
'# Compare cross-validation performance\nfrom sklearn.model_selection import cross_val_score\nfrom sklearn.ensemble import RandomForestRegressor\nmodel = RandomForestRegressor(random_state=42)\nscores = cross_val_score(model, X, y, cv=5)\nprint(scores.mean())',
'# A small neural network\nimport torch.nn as nn\nmodel = nn.Sequential(\n    nn.Linear(32, 64),\n    nn.ReLU(),\n    nn.Linear(64, 10)\n)',
'# Proportional controller for a robot joint\ndef control(target, position, gain=0.8):\n    error = target - position\n    command = gain * error\n    return max(-1.0, min(1.0, command))',
'# Daily returns and annualized volatility\nimport numpy as np\nreturns = prices.pct_change().dropna()\nvolatility = returns.std() * np.sqrt(252)\nprint(volatility)',
'# Explore missing values before analysis\nimport pandas as pd\ndf = pd.read_csv("observations.csv")\nprint(df.isna().mean().sort_values(ascending=False))\nprint(df.describe())',
'# Solve a linear system Ax = b\nimport numpy as np\nA = np.array([[2., 1.], [1., 3.]])\nb = np.array([5., 7.])\nx = np.linalg.solve(A, b)\nprint(x)'
];return snippets[d.id]}
async function copySnippet(id){try{await navigator.clipboard.writeText(snippet(domains[id]));toast('Code copied')}catch{modal('Copy this snippet',`<pre>${escapeHTML(snippet(domains[id]))}</pre>`)}}
const videoTitles=["Stanford CS229 — Lecture 1","Algorithms and Data Structures","Stanford CS229 — Lecture 1","But what is a neural network?","Foundations of Robot Motion","How the Economic Machine Works","Learn Data Science","Vectors"];
function videoRow(d){return `<article class="list-card resource"><span class="small-icon">${icon('play')}</span><div class="resource-content"><h3>${videoTitles[d.id]}</h3><p>YouTube reference · Internet required</p></div><a href="https://www.youtube.com/watch?v=${d.video}" target="_blank" rel="noopener noreferrer" aria-label="Play ${d.name} foundation lecture on YouTube">${icon('play')}</a></article>`}
function pdfRow(d){return `<article class="list-card resource resource-type-pdf"><span class="small-icon">${icon('file')}</span><div class="resource-content"><h3>${escapeHTML(d.name)} — Study planner</h3><p>PDF · Generated planner · Download for offline use</p><span class="resource-badge">${escapeHTML(d.name)}</span></div><button onclick="downloadPDF(${d.id})" aria-label="Download ${escapeHTML(d.name)} study planner">${icon('download')}</button></article>`}
function downloadPDF(id){const d=domains[id];const clean=s=>s.replace(/[^\x20-\x7E]/g,' ').replace(/[\\()]/g,'\\$&');const lines=['ZETA STUDY PLANNER',d.name,'Project: '+d.project,'','Learning roadmap:',...d.roadmap.map((r,i)=>(i+1)+'. '+r),'','This week: '+d.task,'','Session date: __________________','Time spent: ____________________','Notes:','________________________________','________________________________','Generated demo planner - save locally for offline use.'];const stream='BT /F1 12 Tf 50 790 Td '+lines.map((s,i)=>(i?'0 -28 Td ':'')+'('+clean(s)+') Tj').join('\n')+' ET';const objs=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`];let pdf='%PDF-1.4\n',offsets=[0];objs.forEach((o,i)=>{offsets.push(pdf.length);pdf+=`${i+1} 0 obj\n${o}\nendobj\n`});const xref=pdf.length;pdf+=`xref\n0 6\n0000000000 65535 f \n${offsets.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n ').join('\n')}\ntrailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;const url=URL.createObjectURL(new Blob([pdf],{type:'application/pdf'}));const a=document.createElement('a');a.href=url;a.download=`zeta-${d.name.replace(/[^a-z0-9]/gi,'-').toLowerCase()}-planner.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Study planner downloaded')}
function baseProfilePage(){pageHeader('Your profile','A SPACE THAT GROWS WITH YOU');main.innerHTML=`<section class="page-sheet"><div class="row"><div><div class="profile-avatar">AK</div><h2>${escapeHTML(profile.name)}</h2><p class="subtitle">Lifelong learner · Personal workspace</p></div><span class="pill">Demo account</span></div><form onsubmit="saveProfile(event)"><label class="field" for="name">Display name</label><input class="input" id="name" required maxlength="40" value="${escapeHTML(profile.name)}"><label class="field" for="goal">Your learning intention</label><input class="input" id="goal" maxlength="140" value="${escapeHTML(profile.goal)}"><button class="primary" type="submit" style="width:100%;margin-top:12px">Save changes</button></form></section><section class="section"><div class="list-card"><h3>Stored on this device</h3><p>Your profile and task checkmarks are saved in this browser. Learning metrics, projects, and activity are example content.</p></div><div class="list-card"><h3>Offline resources</h3><p>Downloaded PDF planners work offline. YouTube references need an internet connection.</p></div></section>`}
function profilePage(){baseProfilePage();main.insertAdjacentHTML('beforeend',courseAnalyticsHTML()+studySessionHTML());}
function saveProfile(e){e.preventDefault();const name=document.getElementById('name').value.trim();if(!name){toast('Enter a display name');return}profile={name,goal:document.getElementById('goal').value.trim()};if(save('nexus-profile',profile)){profilePage();toast('Your profile has been saved')}}
function activityPage(){pageHeader('Recent activity','YOUR LEARNING, IN MOTION');main.innerHTML=`<section class="page-sheet"><div class="section-heading"><h2>Your latest updates</h2><span class="pill">Sample stream</span></div>${activityRows(true)}</section>`}
