if(catalog.domains.length)domains.splice(0,domains.length,...catalog.domains.map((d,i)=>({...d,id:d.id??i,progress:d.progress??(i<8?[75,62,68,42,35,56,81,73][i]:0),video:d.video||['jGwO_UgTS7I','8hly31xKli0','jGwO_UgTS7I','aircAruvnKk','csYtU2GY7FY','PHe0bXAIuk0','ua-CiDNNj30','fNk_zzaMoSs'][i],bg:d.bg||'#cdeffa',color:d.color||'#486a70',icon:d.icon||'book'})));
