function renderGreeting(){return `<div class="top"><button class="profile-trigger" onclick="navigate('profile')" aria-label="Edit your profile"><span class="avatar">AK</span><span class="greeting">Welcome back,<strong>${escapeHTML(profile.name)}</strong></span></button><button class="notification" aria-label="View notifications" onclick="notifications()">${icon('bell')}</button></div>`}
function pageHeader(title,subtitle){header.className='compact';header.innerHTML=`<div class="page-header"><button onclick="navigate('${page==='domain'?'domains':page==='course'?'courses':'home'}')" aria-label="${page==='domain'?'Back to domains':page==='course'?'Back to courses':'Back to home'}">${icon('back')}</button><h1>${escapeHTML(title)}</h1><button class="avatar compact-avatar" onclick="navigate('profile')" aria-label="Edit your profile">AK</button></div><div class="eyebrow">${escapeHTML(subtitle)}</div>`}
function renderNav(){nav.innerHTML=[['home','home','Home'],['domains','domains','Domains'],['courses','academy','Courses'],['knowledge','book','Knowledge'],['jobs','briefcase','Jobs']].map(([id,ic,label])=>`<button onclick="navigate('${id}')" class="${page===id||(page==='domain'&&id==='domains')||(page==='course'&&id==='courses')?'active':''}" ${page===id?'aria-current="page"':''}><span class="nav-icon">${icon(ic)}</span>${label}</button>`).join('')}
function navigate(next){page=next;renderNav();main.className='fade';({home,domains:domainList,analytics:profilePage,courses:academy,knowledge,profile:profilePage,activity:activityPage,jobs}[next]||home)();window.scrollTo({top:0,behavior:'instant'})}
function domainGrid(){return `<div class="domains-grid">${domains.slice(0,8).map(d=>`<button class="domain" onclick="openDomain(${d.id})"><span class="domain-icon" style="background:${d.bg};color:${d.color}">${icon(d.icon)}</span><span class="domain-label">${escapeHTML(d.name)}</span></button>`).join('')}</div>`}
function home(){basehome();const activity=main.querySelector('.section');const content=document.createElement('div');content.innerHTML=explorePreview()+featuredRoles(3)+featuredSkills(8)+roleComparison(4);main.insertBefore(content,activity);}
function explorePreview(){const names=['Blockchain','Full Stack','DevOps','Cybersecurity','AI Compilers','Mobile'];let picks=names.map(n=>domains.find(d=>d.name.toLowerCase().includes(n.toLowerCase()))).filter(Boolean);if(!picks.length)picks=domains.slice(8,14);return `<section class="section"><div class="section-heading"><div><span class="eyebrow light">FIND YOUR NEXT CHAPTER</span><h2>Explore domains</h2></div><span class="pill">${domains.length} paths</span></div><p class="subtitle">From your first line of code to your next specialization.</p><div class="catalog-preview">${picks.map(d=>`<button class="preview-card" onclick="openDomain(${d.id})"><span class="preview-icon" style="background:${d.bg};color:${d.color}">${icon(d.icon)}</span><strong>${escapeHTML(d.name)}</strong><small>${escapeHTML(d.category||'Technology')}</small>${icon('arrow')}</button>`).join('')}</div><button class="secondary full" onclick="navigate('domains')">Browse all ${domains.length} domains ${icon('arrow')}</button></section>`}
function featuredRoles(count=6){return `<section class="section"><div class="section-heading"><h2>Top roles</h2><button class="text-button" onclick="navigate('jobs')">Explore careers ${icon('arrow')}</button></div><p class="subtitle">Featured career picks. Build skills with a direction.</p><div class="role-cards">${catalog.roles.slice(0,count).map((r,i)=>`<button class="role-card" onclick="roleDetail('${r.id}')"><span class="role-number">0${i+1}</span><div><strong>${escapeHTML(r.title)}</strong><p>${escapeHTML(r.package)}</p><small>India · Indicative CTC · 0–3 years</small></div>${icon('arrow')}</button>`).join('')}</div></section>`}
function skillName(s){return typeof s==='string'?s:s.name||s.title}
function featuredSkills(count=12){const preferred=['Python','SQL','JavaScript','TypeScript','Git','Docker','Linux','React','Machine Learning','Data Analysis','Cloud Computing','Cybersecurity'];const selected=[...preferred.filter(n=>catalog.skills.some(s=>skillName(s).toLowerCase()===n.toLowerCase())).map(n=>catalog.skills.find(s=>skillName(s).toLowerCase()===n.toLowerCase())),...catalog.skills.filter(s=>!preferred.some(n=>n.toLowerCase()===skillName(s).toLowerCase()))];return `<section class="section"><div class="section-heading"><h2>Top skills</h2><span class="pill">Featured</span></div><div class="skill-chips">${selected.slice(0,count).map(s=>`<button onclick="exploreSkill('${escapeHTML(skillName(s)).replace(/'/g,'&#39;')}')">${escapeHTML(skillName(s))}<span>↗</span></button>`).join('')}</div></section>`}
function exploreSkill(skill){domainSearch=skill;domainCategory='all';showBookmarks=false;domainsShown=20;navigate('domains')}
function roleComparison(count=8){return `<section class="section"><div class="section-heading"><h2>Compare career paths</h2><span class="pill">India</span></div><p class="subtitle">Indicative annual CTC for 0–3 years of experience. Packages vary by employer, city, and skill; these are guides, not offers.</p><div id="roleTable${count}" class="comparison-block"><div class="table-scroll" role="region" aria-label="Career comparison; scroll horizontally" tabindex="0"><table><caption>Featured roles · responsibilities, qualifications and compensation</caption><thead><tr><th scope="col">Role</th><th scope="col">Responsibilities</th><th scope="col">Annual package</th><th scope="col">Qualifications</th></tr></thead><tbody>${catalog.roles.slice(0,count).map(r=>`<tr><th scope="row"><button onclick="roleDetail('${r.id}')">${escapeHTML(r.title)}</button></th><td>${escapeHTML(Array.isArray(r.responsibilities)?r.responsibilities.join('; '):r.responsibilities)}</td><td>${escapeHTML(r.package)}<br>${r.salarySource?`<a href="${r.salarySource}" target="_blank" rel="noopener noreferrer">Salary source ↗</a>`:'<small>Employer-specific; no range quoted</small>'}</td><td>${escapeHTML(Array.isArray(r.qualifications)?r.qualifications.join('; '):r.qualifications)}</td></tr>`).join('')}</tbody></table></div><p class="table-hint">Swipe to compare responsibilities and qualifications →</p>${count<catalog.roles.length?`<button class="secondary full" onclick="expandRolesTable(this)">Compare all ${catalog.roles.length} roles</button>`:''}</div></section>`}
function expandRolesTable(button){const block=button.closest('.comparison-block');const temp=document.createElement('div');temp.innerHTML=roleComparison(catalog.roles.length);block.replaceWith(temp.querySelector('.comparison-block'))}
function categoryOptions(value='all'){return `<option value="all">All categories</option>${catalog.categories.map(c=>{const n=typeof c==='string'?c:c.name;return `<option value="${escapeHTML(n)}" ${value===n?'selected':''}>${escapeHTML(n)}</option>`}).join('')}`}
function domainOptions(value='all'){return `<option value="all">All domains</option>${domains.map(d=>`<option value="${d.id}" ${String(value)===String(d.id)?'selected':''}>${escapeHTML(d.name)}</option>`).join('')}`}
function domainList(){pageHeader('Explore domains','A WORLD OF POSSIBILITIES');main.innerHTML=`<section class="page-sheet domain-browser"><div class="section-heading"><h2>Find your learning path</h2><span class="pill">${domains.length} domains</span></div>${categoryTiles()}<div class="catalog-filter-panel"><label class="field" for="domainSearch">${icon('search')} Search domains or skills</label><input class="input" id="domainSearch" type="search" placeholder="Try blockchain, Python, cloud…" value="${escapeHTML(domainSearch)}" oninput="domainSearch=this.value;domainsShown=20;renderDomainResults()"><div class="filter-pair"><label>Category<select class="input" onchange="setDomainCategory(this.value)">${categoryOptions(domainCategory)}</select></label><button id="bookmarkFilter" class="secondary ${showBookmarks?'selected':''}" aria-pressed="${showBookmarks}" onclick="showBookmarks=!showBookmarks;this.setAttribute('aria-pressed',showBookmarks);this.classList.toggle('selected',showBookmarks);renderDomainResults()">${icon('bookmark')} Saved</button></div></div><div id="domainResults"></div></section>${featuredRoles()}${featuredSkills()}${roleComparison()}<section class="section"><h2>Recommended starting paths</h2><div class="list-card"><h3>Build a strong foundation</h3><p>Start with Computer Science and Mathematics, then choose a specialization that fits your curiosity.</p><button class="text-button" onclick="openDomain(1)">Start with Computer Science ${icon('arrow')}</button></div><div class="list-card"><h3>Learn by building</h3><p>Each domain includes a practical project, progressive roadmap, and trusted documentation.</p><button class="text-button" onclick="openDomain(0)">Explore your first AI project ${icon('arrow')}</button></div></section>`;renderDomainResults()}
function renderDomainResults(){const filtered=domains.filter(d=>(domainCategory==='all'||d.category===domainCategory)&&(!showBookmarks||bookmarks.includes(d.id))&&[d.name,d.category,d.description,...(d.skills||[]),...(d.roles||[])].join(' ').toLowerCase().includes(domainSearch.toLowerCase()));document.getElementById('domainResults').innerHTML=`<p class="result-count">${filtered.length} learning paths ${showBookmarks?'in your bookmarks':''}</p><div class="domain-catalog">${filtered.slice(0,domainsShown).map(d=>`<article class="catalog-card"><button class="catalog-main" onclick="openDomain(${d.id})"><span class="preview-icon" style="background:${d.bg};color:${d.color}">${icon(d.icon)}</span><span><strong>${escapeHTML(d.name)}</strong><small>${escapeHTML(d.category||'Technology')}</small><p>${escapeHTML(d.description)}</p></span></button><button class="bookmark-button ${bookmarks.includes(d.id)?'saved':''}" aria-label="${bookmarks.includes(d.id)?'Remove bookmark for':'Bookmark'} ${escapeHTML(d.name)}" aria-pressed="${bookmarks.includes(d.id)}" onclick="toggleBookmark(${d.id},this)">${icon('bookmark')}</button></article>`).join('')}</div>${!filtered.length?'<div class="empty">No paths match these filters.<button class="text-button" onclick="resetDomains()">Reset filters</button></div>':''}${filtered.length>domainsShown?`<button class="secondary full" onclick="domainsShown+=20;renderDomainResults()">Load more domains · ${filtered.length-domainsShown} remaining</button>`:''}`}
function resetDomains(){domainSearch='';domainCategory='all';showBookmarks=false;domainList()}
function toggleBookmark(id,button){bookmarks=bookmarks.includes(id)?bookmarks.filter(n=>n!==id):[...bookmarks,id];save('zeta-bookmarks',bookmarks);const saved=bookmarks.includes(id);button.classList.toggle('saved',saved);button.setAttribute('aria-pressed',saved);button.setAttribute('aria-label',`${saved?'Remove bookmark for':'Bookmark'} ${domains.find(d=>d.id===id).name}`);toast(saved?'Domain bookmarked':'Bookmark removed');if(showBookmarks&&page==='domains')renderDomainResults()}
function knowledge(){pageHeader('Knowledge hub','YOUR NEXT BREAKTHROUGH IS HERE');main.innerHTML=`<section class="page-sheet"><div class="section-heading"><h2>Learn at every level</h2><span class="pill">Trusted links</span></div><label class="field icon-label" for="knowledgeSearch">${icon('search')} Search resources</label><input id="knowledgeSearch" class="input" type="search" placeholder="Search topics or documentation…" value="${escapeHTML(knowledgeState.search)}" oninput="setKnowledge('search',this.value)">${knowledgeFormatPills()}${domainChipUI()}<div class="knowledge-filters"><label>Domain<select class="input" onchange="setKnowledge('domain',this.value)">${domainOptions(knowledgeState.domain)}</select></label><label>Category<select class="input" onchange="setKnowledge('category',this.value)">${categoryOptions(knowledgeState.category)}</select></label><label>Level<select class="input" onchange="setKnowledge('level',this.value)">${['all','beginner','intermediate','advanced'].map(n=>`<option value="${n}" ${knowledgeState.level===n?'selected':''}>${n==='all'?'All levels':n}</option>`).join('')}</select></label><label>Format<select class="input" onchange="setKnowledge('type',this.value)">${formatOptions(knowledgeState.type)}</select></label><label>Source<select class="input" onchange="setKnowledge('source',this.value)">${sourceOptions(knowledgeState.source)}</select></label></div><p class="subtitle">Official resources open online. Platform discovery links find courses or videos; some require enrolment. Only downloaded planners work offline.</p></section><section id="resources" class="section knowledge-resource-list"></section>`;renderDomainChips();renderResources()}
function setKnowledge(key,value){knowledgeState[key]=value;if(key==='category'&&knowledgeState.domain!=='all'){const selected=domains.find(d=>String(d.id)===String(knowledgeState.domain));if(value!=='all'&&selected?.category!==value)knowledgeState.domain='all'}knowledgeState.limit=20;syncKnowledgeControls();renderResources();if(key==='domain')main.querySelector(`[data-domain="${knowledgeState.domain}"]`)?.scrollIntoView({block:'nearest',inline:'nearest'})}
function renderResources(){const k=knowledgeState;const found=allResources().filter(r=>(k.domain==='all'||String(r.domain.id)===k.domain)&&(k.category==='all'||r.domain.category===k.category)&&(k.level==='all'||r.level===k.level)&&resourceTypeMatches(r,k.type)&&(k.source==='all'||r.source===k.source)&&[r.title,r.domain.name,r.domain.category].join(' ').toLowerCase().includes(k.search.toLowerCase()));document.getElementById('resources').innerHTML=`<p class="result-count">${found.length} resources · showing ${Math.min(found.length,k.limit)}</p>${found.slice(0,k.limit).map(r=>`${r.generated?pdfRow(r.domain):resourceRow(r)}`).join('')}${!found.length?'<div class="empty">No resources match these filters.<button class="text-button" onclick="resetKnowledge()">Reset filters</button></div>':''}${found.length>k.limit?`<button class="secondary full" onclick="knowledgeState.limit+=20;renderResources()">Load 20 more resources</button>`:''}`}
function resetKnowledge(){knowledgeState={search:'',domain:'all',category:'all',level:'all',type:'all',limit:20};knowledge()}
function roleDetail(id){const r=catalog.roles.find(r=>String(r.id)===String(id));if(!r)return;const d=domains.find(d=>(r.domainNames||[]).includes(d.name));modal(r.title,`<span class="pill">India · 0–3 years · Indicative CTC</span><h3>${escapeHTML(r.package)}</h3><p><strong>Responsibilities</strong><br>${escapeHTML(Array.isArray(r.responsibilities)?r.responsibilities.join('; '):r.responsibilities)}</p><p><strong>Qualifications</strong><br>${escapeHTML(Array.isArray(r.qualifications)?r.qualifications.join('; '):r.qualifications)}</p><p><strong>Skills</strong><br>${escapeHTML((r.skills||[]).join(' · '))}</p>${r.salarySource?`<a class="source-link" href="${r.salarySource}" target="_blank" rel="noopener noreferrer">Salary reference ↗</a>`:'<p>No comparable junior salary range is quoted for this specialization.</p>'}<div class="modal-actions">${d?`<button class="secondary" onclick="document.getElementById('dialog').close();openDomain(${d.id})">Learn this domain</button>`:''}<button class="primary" onclick="document.getElementById('dialog').close();findJobs('${escapeHTML(r.title).replace(/'/g,'&#39;')}')">Find job opportunities</button></div>`)}
function findJobs(title){jobsState={search:title,category:'all',domain:'all',saved:false};navigate('jobs')}
function jobs(){pageHeader('Career opportunities','LEARN WITH YOUR NEXT ROLE IN MIND');main.innerHTML=`<section class="page-sheet"><div class="section-heading"><h2>Your next direction</h2><span class="pill">India</span></div><p class="subtitle">Explore roles, save a shortlist, and search real job boards. ZETA does not host vacancies.</p><label class="field" for="jobSearch">Role or skill</label><input class="input" id="jobSearch" type="search" placeholder="Software engineer, Python, cloud…" value="${escapeHTML(jobsState.search)}" oninput="jobsState.search=this.value;renderJobs()"><div class="knowledge-filters"><label>Category<select class="input" onchange="jobsState.category=this.value;renderJobs()">${categoryOptions(jobsState.category)}</select></label><label>Domain<select class="input" onchange="jobsState.domain=this.value;renderJobs()">${domainOptions(jobsState.domain)}</select></label><label>Location<input class="input" value="${escapeHTML(jobPrefs.location)}" maxlength="60" onchange="jobPrefs.location=this.value.trim()||'India';save('zeta-job-preferences',jobPrefs);renderJobs()"></label><label>Experience<select class="input" onchange="jobPrefs.experience=this.value;save('zeta-job-preferences',jobPrefs);renderJobs()">${['0–3 years','3–6 years','6+ years'].map(n=>`<option ${jobPrefs.experience===n?'selected':''}>${n}</option>`).join('')}</select></label></div><button id="savedJobs" class="secondary full ${jobsState.saved?'selected':''}" aria-pressed="${jobsState.saved}" onclick="jobsState.saved=!jobsState.saved;this.classList.toggle('selected',jobsState.saved);this.setAttribute('aria-pressed',jobsState.saved);renderJobs()">${icon('bookmark')} ${jobsState.saved?'Showing your shortlist':'Show saved shortlist'}</button><div id="jobCustom"></div><div id="jobResults"></div></section>`;renderJobs()}
function renderJobs(){const j=jobsState;document.getElementById('jobCustom').innerHTML=j.search.trim()?`<div class="list-card"><h3>Search live opportunities</h3><p>${escapeHTML(j.search)} · ${escapeHTML(jobPrefs.location)} · ${escapeHTML(jobPrefs.experience)}</p><div class="job-links">${jobLinks(j.search.trim())}</div><p class="job-note">Job boards apply their own experience filters. Salary guides below remain for 0–3 years.</p></div>`:'';const found=catalog.roles.filter(r=>(!j.saved||shortlist.includes(r.id))&&[r.title,...(r.skills||[])].join(' ').toLowerCase().includes(j.search.toLowerCase())&&(j.domain==='all'||r.domainNames?.includes(domains.find(d=>String(d.id)===j.domain)?.name))&&(j.category==='all'||domains.some(d=>d.category===j.category&&r.domainNames?.includes(d.name))));document.getElementById('jobResults').innerHTML=`<p class="result-count">${found.length} career paths · ${escapeHTML(jobPrefs.location)} · ${escapeHTML(jobPrefs.experience)}</p>${found.map(r=>`<article class="job-card"><div class="row"><button class="job-title" onclick="roleDetail('${r.id}')">${escapeHTML(r.title)}</button><button class="bookmark-button ${shortlist.includes(r.id)?'saved':''}" aria-label="${shortlist.includes(r.id)?'Remove saved':'Save'} ${escapeHTML(r.title)}" aria-pressed="${shortlist.includes(r.id)}" onclick="toggleJob('${r.id}',this)">${icon('bookmark')}</button></div><p>${escapeHTML(r.package)} <small>· India annual CTC, 0–3 years</small></p><div class="job-skills">${(r.skills||[]).slice(0,3).map(s=>`<span class="tag">${escapeHTML(s)}</span>`).join('')}</div><div class="job-links">${jobLinks(r.title)}</div><small class="job-note">External searches · availability and requirements vary</small></article>`).join('')}${!found.length?'<div class="empty">No career paths match your selection.<button class="text-button" onclick="jobsState={search:\'\',category:\'all\',domain:\'all\',saved:false};jobs()">Reset filters</button></div>':''}`}
function jobLinks(title){const location=jobPrefs.location||'India';return `<a href="https://www.linkedin.com/jobs/search/?keywords=${encodeURIComponent(title)}&location=${encodeURIComponent(location)}" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a><a href="https://www.naukri.com/${encodeURIComponent(title.toLowerCase().replace(/[^a-z0-9]+/g,'-'))}-jobs-in-${encodeURIComponent(location.toLowerCase().replace(/[^a-z0-9]+/g,'-'))}" target="_blank" rel="noopener noreferrer">Naukri ↗</a><a href="https://in.indeed.com/jobs?q=${encodeURIComponent(title)}&l=${encodeURIComponent(location)}" target="_blank" rel="noopener noreferrer">Indeed ↗</a>`}
function toggleJob(id,button){const r=catalog.roles.find(r=>String(r.id)===String(id));if(!r)return;shortlist=shortlist.includes(r.id)?shortlist.filter(n=>n!==r.id):[...shortlist,r.id];save('zeta-shortlist',shortlist);button.classList.toggle('saved',shortlist.includes(r.id));button.setAttribute('aria-pressed',shortlist.includes(r.id));toast(shortlist.includes(r.id)?'Career path saved':'Removed from shortlist');if(jobsState.saved&&page==='jobs')renderJobs()}
function categoryTiles(){return `<section class="category-section"><div class="section-heading"><h3>Explore by category</h3><button class="text-button category-all ${domainCategory==='all'?'selected':''}" data-category="all" aria-pressed="${domainCategory==='all'}" onclick="setDomainCategory('all')">View all</button></div><div class="category-grid">${catalog.categories.map((c,i)=>`<button class="category-tile ${domainCategory===c?'selected':''}" data-category="${escapeHTML(c)}" aria-pressed="${domainCategory===c}" onclick="setDomainCategory(this.dataset.category)"><span style="background:${['#c8f4df','#d2e4ff','#fff1b8','#ffe0c9'][i%4]}">${icon(['brain','code','analytics','network','robot','book','algorithm','math','trend','domains'][i%10])}</span><strong>${escapeHTML(c)}</strong><small>${domains.filter(d=>d.category===c).length} domains</small></button>`).join('')}</div></section>`}
function setDomainCategory(category){domainCategory=category;domainsShown=20;main.querySelectorAll('[data-category]').forEach(el=>{el.classList.toggle('selected',el.dataset.category===category);el.setAttribute('aria-pressed',el.dataset.category===category)});const select=main.querySelector('.filter-pair select');if(select)select.value=category;renderDomainResults()}
function knowledgeFormatPills(){return '<div class="knowledge-format-pills" aria-label="Resource formats">'+[['all','All','domains'],['pdf','PDF','file'],['video','Videos & courses','play'],['course','Courses','book'],['doc','Docs','code']].map(([value,label,ic])=>`<button class="knowledge-format-pill ${knowledgeState.type===value?'selected':''}" data-format="${value}" aria-pressed="${knowledgeState.type===value}" onclick="setKnowledge('type','${value}')">${icon(ic)}<span>${label}</span></button>`).join('')+'</div><p class="resource-filter-hint">Swipe to browse resource formats →</p>'}
function domainChipUI(){return `<section class="domain-chip-section"><div class="section-heading"><h3>Filter by domain</h3><span class="pill">${domains.length} fields</span></div><label class="sr-only" for="chipSearch">Find a domain filter</label><input class="input chip-search" id="chipSearch" type="search" placeholder="Find a domain in the filters…" value="${escapeHTML(chipSearch)}" oninput="chipSearch=this.value;renderDomainChips()"><div id="domainChips" class="domain-chips" aria-label="Domain filters"></div><p class="chip-hint">Swipe to explore all domains →</p></section>`}
function renderDomainChips(){const holder=document.getElementById('domainChips');if(!holder)return;const selected=knowledgeState.domain;const filtered=domains.filter(d=>d.name.toLowerCase().includes(chipSearch.toLowerCase()));holder.innerHTML=`<button data-domain="all" class="domain-chip ${selected==='all'?'selected':''}" aria-pressed="${selected==='all'}" onclick="selectDomainChip('all')">All domains</button>${filtered.map(d=>`<button data-domain="${d.id}" class="domain-chip ${String(selected)===String(d.id)?'selected':''}" aria-pressed="${String(selected)===String(d.id)}" onclick="selectDomainChip('${d.id}')">${escapeHTML(d.name)}</button>`).join('')}${!filtered.length?'<span class="chip-empty">No matching domain. Clear the filter search.</span>':''}`}
function selectDomainChip(id){knowledgeState.domain=id;const d=domains.find(d=>String(d.id)===id);if(d&&knowledgeState.category!=='all'&&d.category!==knowledgeState.category)knowledgeState.category='all';knowledgeState.limit=20;syncKnowledgeControls();renderResources();main.querySelector(`[data-domain="${id}"]`)?.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'})}
function syncKnowledgeControls(){const selects=main.querySelectorAll('.knowledge-filters select');['domain','category','level','type','source'].forEach((key,i)=>{if(selects[i])selects[i].value=knowledgeState[key]});renderDomainChips();main.querySelectorAll('.knowledge-format-pill').forEach(b=>{const active=b.dataset.format===knowledgeState.type;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',active)})}
const workspaceTabs=[['about','About'],['basics','Basics'],['roadmap','Roadmap'],['resources','Resources'],['jobs','Jobs'],['insights','Insights & Updates']];
function getDomainContent(d){return window.ZETA_DOMAIN_CONTENT?.[d.id]||{about:d.description,applications:[d.project],basics:d.roadmap.slice(0,3),prerequisites:['Comfort with basic computing and problem solving','A willingness to learn through practical experiments'],subjects:d.skills||[],insights:['Build a small project before adding complexity.','Use the official resources to check current guidance.']}}
function openDomain(id){const d=domains.find(d=>d.id===id);if(!d)return;currentDomainId=id;currentDomainTab='about';domainResourceState={search:'',type:'all',source:'all',level:'all',filter:'all'};page='domain';renderNav();pageHeader(d.name,'YOUR DOMAIN WORKSPACE');const progress=Math.round([0,1,2].filter(i=>tasks[`${id}-${i}`]).length/3*100);main.innerHTML=`<section class="page-sheet workspace-hero"><div class="row"><span class="pill">${escapeHTML(d.category)}</span><button class="bookmark-button ${bookmarks.includes(id)?'saved':''}" onclick="toggleBookmark(${id},this)" aria-pressed="${bookmarks.includes(id)}" aria-label="Bookmark ${escapeHTML(d.name)}">${icon('bookmark')}</button></div><div class="roadmap-intro"><div class="workspace-icon" style="background:${d.bg};color:${d.color}">${icon(d.icon)}</div><div class="workspace-heading"><h2>${escapeHTML(d.name)}</h2><p>${escapeHTML(d.description)}</p></div><div class="ring" style="--progress:${progress}%"><span>${progress}%<small>tasks complete</small></span></div></div></section><div class="workspace-tabs" role="tablist" aria-label="${escapeHTML(d.name)} sections">${workspaceTabs.map(([key,label],i)=>`<button id="tab-${key}" role="tab" aria-controls="workspacePanel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-tab="${key}" onclick="selectWorkspaceTab('${key}')" onkeydown="workspaceKey(event,'${key}')">${label}</button>`).join('')}</div><p class="workspace-tab-hint">Swipe for all sections →</p><section id="workspacePanel" class="workspace-panel" role="tabpanel" aria-labelledby="tab-about" tabindex="0"></section>`;renderWorkspacePanel();window.scrollTo({top:0,behavior:'instant'})}
function selectWorkspaceTab(tab){currentDomainTab=tab;main.querySelectorAll('[role="tab"]').forEach(el=>{const active=el.dataset.tab===tab;el.setAttribute('aria-selected',active);el.tabIndex=active?0:-1});main.querySelector('#workspacePanel').setAttribute('aria-labelledby','tab-'+tab);renderWorkspacePanel()}
function workspaceKey(event,tab){const keys=workspaceTabs.map(t=>t[0]);let i=keys.indexOf(tab);if(event.key==='ArrowRight')i=(i+1)%keys.length;else if(event.key==='ArrowLeft')i=(i+keys.length-1)%keys.length;else if(event.key==='Home')i=0;else if(event.key==='End')i=keys.length-1;else return;event.preventDefault();selectWorkspaceTab(keys[i]);document.getElementById('tab-'+keys[i]).focus();document.getElementById('tab-'+keys[i]).scrollIntoView({block:'nearest',inline:'nearest'})}
function textList(items){return `<ul class="learning-list">${(items||[]).map(t=>`<li>${escapeHTML(t)}</li>`).join('')}</ul>`}
function taskHTML(d){return `<div class="list-card">${[d.task,'Complete the next roadmap lesson','Write a short learning reflection'].map((t,i)=>`<label class="task"><input type="checkbox" ${tasks[`${d.id}-${i}`]?'checked':''} onchange="updateTask('${d.id}-${i}',this.checked)"><span>${escapeHTML(t)}</span></label>`).join('')}</div>`}
function renderWorkspacePanel(){const d=domains.find(d=>d.id===currentDomainId),c=getDomainContent(d),panel=document.getElementById('workspacePanel');if(currentDomainTab==='about')panel.innerHTML=`<div class="panel-heading"><span class="eyebrow light">THE BIG PICTURE</span><h2>What is ${escapeHTML(d.name)}?</h2></div><p class="orientation-copy">${escapeHTML(c.about)}</p><section class="section"><h3>Where it’s used</h3>${textList(c.applications)}</section><section class="section"><h3>Subjects & specializations</h3><div class="subject-grid">${c.subjects.map(s=>`<span>${escapeHTML(s)}</span>`).join('')}</div></section><section class="section"><h3>Skills you’ll build</h3><div class="skill-chips">${(d.skills||[]).map(s=>`<button onclick="exploreSkill('${escapeHTML(s).replace(/'/g,'&#39;')}')">${escapeHTML(s)} ↗</button>`).join('')}</div></section><button class="secondary full" onclick="browseDomainCourses(${d.id})">Explore related course packages →</button><button class="primary full" onclick="selectWorkspaceTab('basics')">Start with the basics ${icon('arrow')}</button>`;
else if(currentDomainTab==='basics')panel.innerHTML=`<div class="panel-heading"><span class="eyebrow light">BUILD YOUR FOUNDATION</span><h2>The basics, explained</h2></div>${c.basics.map((b,i)=>`<article class="concept-card"><span>0${i+1}</span><p>${escapeHTML(b)}</p></article>`).join('')}<section class="section"><h3>Before you begin</h3>${textList(c.prerequisites)}</section><section class="section"><div class="roadmap-teaser"><span class="eyebrow light">A CLEAR PATH FORWARD</span><h3>From foundations to your capstone</h3><p>Follow linked resources, build at each stage, and check your understanding before moving on.</p><button class="primary full" onclick="selectWorkspaceTab('roadmap')">Open your learning roadmap →</button></div></section><section class="section"><h3>Put it into practice</h3><article class="list-card"><h3>${escapeHTML(d.project)}</h3><p>Build a small working prototype, document your decisions, and create a short demonstration.</p></article></section><section class="section"><h3>Your tasks & targets</h3>${taskHTML(d)}</section>`;
else if(currentDomainTab==='roadmap')panel.innerHTML=roadmapHTML(d);
else if(currentDomainTab==='resources')panel.innerHTML=domainResourcesHTML(d);
else if(currentDomainTab==='jobs'){const roles=catalog.roles.filter(r=>r.domainNames?.includes(d.name)||(d.roles||[]).includes(r.title));panel.innerHTML=`<div class="panel-heading"><span class="eyebrow light">TURN KNOWLEDGE INTO OPPORTUNITY</span><h2>Careers in ${escapeHTML(d.name)}</h2></div><p class="subtitle">Indicative India annual CTC for 0–3 years. These are career guides, not hosted vacancies.</p>${roles.map(r=>`<article class="domain-job-card"><div class="row"><h3>${escapeHTML(r.title)}</h3><button class="bookmark-button ${shortlist.includes(r.id)?'saved':''}" aria-label="Save ${escapeHTML(r.title)}" aria-pressed="${shortlist.includes(r.id)}" onclick="toggleJob('${r.id}',this)">${icon('bookmark')}</button></div><strong class="package">${escapeHTML(r.package)}</strong><h4>What you’ll do</h4><p>${escapeHTML(r.responsibilities)}</p><h4>Qualifications</h4><p>${escapeHTML(r.qualifications)}</p><div class="job-skills">${r.skills.slice(0,4).map(s=>`<span class="tag">${escapeHTML(s)}</span>`).join('')}</div>${r.salarySource?`<a class="source-link" href="${r.salarySource}" target="_blank" rel="noopener noreferrer">Salary source ↗</a>`:''}<div class="job-links">${jobLinks(r.title)}</div></article>`).join('')}${!roles.length?`<article class="list-card"><h3>Explore related opportunities</h3><p>${escapeHTML((d.roles||[]).join(' · ')||d.name+' specialist')}</p><div class="job-links">${jobLinks(d.name)}</div></article>`:''}<button class="secondary full" onclick="jobsState={search:'',category:'all',domain:'${d.id}',saved:false};navigate('jobs')">Open filtered Jobs portal ${icon('arrow')}</button>`}
else panel.innerHTML=`<div class="panel-heading"><span class="eyebrow light">REFLECT. PRACTICE. STAY CURIOUS.</span><h2>Insights & updates</h2></div><p class="subtitle">Editorial learning guidance and your device-local progress. This is not a live news feed.</p>${c.insights.map((t,i)=>`<article class="insight-card"><span>${icon(i?'trend':'book')}</span><p>${escapeHTML(t)}</p></article>`).join('')}<section class="section"><div class="section-heading"><h3>Your learning updates</h3><span class="pill">This device</span></div><div id="localUpdates">${localUpdatesHTML(d.id)}</div></section><section class="section"><h3>Follow official updates</h3><p class="subtitle">Visit the official resource pages for current documentation and announcements.</p>${(d.resources||[]).slice(0,2).map(resourceRow).join('')}</section>`}
function localUpdatesHTML(id){const d=domains.find(d=>d.id===id),updates=learningUpdates.filter(u=>u.domain===id).slice(0,8);return updates.length?updates.map(u=>`<article class="local-update"><span class="status-icon ${u.completed?'green':'yellow'}"></span><div><strong>${u.completed?'Completed':'Reopened'}: ${escapeHTML([d.task,'Complete the next roadmap lesson','Write a short learning reflection'][u.task])}</strong><time datetime="${u.time}">${new Date(u.time).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'})}</time></div></article>`).join(''):'<div class="list-card"><h3>Your next step starts here</h3><p>Complete or reopen a task in Basics to record your first learning update on this device.</p><button class="text-button" onclick="selectWorkspaceTab(\'basics\')">Go to your tasks →</button></div>'}
function learningPath(d){return window.ZETA_LEARNING_PATHS?.[d.id]||{stages:d.roadmap.map((title,i)=>({id:['beginner','intermediate','advanced','capstone'][i],level:['beginner','intermediate','advanced','advanced'][i],title,goal:d.description,topics:(d.skills||[]).slice(i,i+3),exercise:i===3?d.project:d.task,checkpoint:'Explain what you learned and demonstrate a working example.',resources:(d.resources||[]).filter(r=>r.level===['beginner','intermediate','advanced','advanced'][i])})),resources:[]}}
function normalizeResource(r,d){const type=({documentation:'doc',docs:'doc',youtube:'video',courses:'course'}[r.type]||r.type||'doc').toLowerCase();return {...r,type,source:r.source||(/youtube\.com|youtu\.be/.test(r.url||'')?'youtube':/coursera\.org/.test(r.url||'')?'coursera':/udemy\.com/.test(r.url||'')?'udemy':'other'),level:(r.level||'beginner').toLowerCase(),domain:d}}
function getDomainResources(d){const path=learningPath(d),rows=[...(d.resources||[]),...(path.resources||[]),...path.stages.flatMap(s=>s.resources||[]),{title:d.name+' — Study planner',type:'pdf',source:'other',level:'beginner',generated:true},...(d.id<8?[{title:videoTitles[d.id],type:'video',source:'youtube',level:'beginner',url:'https://www.youtube.com/watch?v='+d.video}]:[])];const seen=new Set();return rows.map(r=>normalizeResource(r,d)).filter(r=>{const key=r.generated?'planner':r.url+'|'+r.level;if(seen.has(key))return false;seen.add(key);return true})}
function allResources(){return domains.flatMap(getDomainResources)}
function resourceRow(r){const type=r.type||'doc',source={youtube:'YouTube',coursera:'Coursera',udemy:'Udemy',github:'GitHub',other:'Official / other'}[r.source]||'Official / other';const typeLabel={pdf:'PDF',video:'Video',course:'Course',repo:'Repository',doc:'Documentation'}[type]||'Reference';return `<article class="list-card resource resource-type-${type}"><span class="small-icon">${icon(type==='video'?'play':type==='pdf'?'file':type==='repo'?'code':'book')}</span><div class="resource-content"><h3>${escapeHTML(r.title)}</h3><p>${typeLabel} · ${escapeHTML(source)} · ${escapeHTML(r.level||'beginner')}</p>${r.discovery?'<small class="discovery-note">Find '+(type==='video'?'videos':'courses')+' · discovery search</small>':''}${r.domain?`<span class="resource-badge">${escapeHTML(r.domain.name)}</span>`:''}</div><a href="${r.url}" target="_blank" rel="noopener noreferrer" aria-label="${r.discovery?'Find learning material for':'Open'} ${escapeHTML(r.title)}">${r.discovery?icon('search'):icon('arrow')}</a></article>`}
function resourceTypeMatches(r,type){return type==='all'||r.type===type||(type==='video'&&r.type==='course')}
function formatOptions(selected){return [['all','All formats'],['pdf','PDF'],['video','Video & courses'],['course','Courses'],['doc','Docs']].map(([value,label])=>`<option value="${value}" ${selected===value?'selected':''}>${label}</option>`).join('')}
function sourceOptions(selected){return [['all','All sources'],['youtube','YouTube'],['coursera','Coursera'],['udemy','Udemy'],['other','Other sources']].map(([value,label])=>`<option value="${value}" ${selected===value?'selected':''}>${label}</option>`).join('')}
function roadmapHTML(d){const path=learningPath(d),completed=path.stages.filter(s=>roadmapProgress[`${d.id}-${s.id}`]).length;return `<div class="panel-heading"><span class="eyebrow light">MAKE YOUR NEXT STEP CLEAR</span><h2>Your learning roadmap</h2></div><p class="subtitle">Work through the stages in order. Build, reflect, and check your understanding before you move on.</p><div class="roadmap-summary"><div><strong id="milestoneCount">${completed} of ${path.stages.length}</strong><span>milestones complete · saved on this device</span></div><div class="milestone-meter"><span id="milestoneMeter" style="width:${completed/path.stages.length*100}%"></span></div></div><div class="roadmap-timeline">${path.stages.map((stage,i)=>`<article class="roadmap-stage ${roadmapProgress[`${d.id}-${stage.id}`]?'completed':''}" id="stage-${stage.id}"><div class="stage-heading"><span class="stage-number">${String(i+1).padStart(2,'0')}</span><div><span class="stage-badge">${stage.id==='capstone'?'CAPSTONE PROJECT':escapeHTML(stage.level)}</span><h3>${escapeHTML(stage.title)}</h3></div></div><p class="stage-goal">${escapeHTML(stage.goal)}</p><h4>What you’ll learn</h4><div class="topic-tags">${(stage.topics||[]).map(t=>`<span>${escapeHTML(t)}</span>`).join('')}</div><div class="practice-block"><h4>Hands-on practice</h4><p>${escapeHTML(stage.exercise)}</p><h4>Your checkpoint</h4><p>${escapeHTML(stage.checkpoint)}</p></div><div class="stage-links">${(stage.resources||[]).map(r=>{const n=normalizeResource(r,d);return `<a href="${n.url}" target="_blank" rel="noopener noreferrer"><span>${icon(n.type==='video'?'play':n.type==='pdf'?'file':'book')}<strong>${escapeHTML(n.title)}</strong></span><small>${n.discovery?'Find '+(n.type==='video'?'videos':'courses'):({doc:'Documentation',pdf:'PDF text',video:'Video',course:'Course'}[n.type]||'Reference')} ↗</small></a>`}).join('')}</div><label class="milestone-check"><input type="checkbox" ${roadmapProgress[`${d.id}-${stage.id}`]?'checked':''} onchange="updateMilestone(${d.id},'${stage.id}',this.checked)"><span>I can demonstrate this checkpoint</span></label></article>`).join('')}</div><p class="subtitle">Milestones track your own learning checkpoints, independently of the three weekly tasks.</p>`}
function updateMilestone(id,stage,checked){roadmapProgress[`${id}-${stage}`]=checked;save('zeta-roadmap-progress',roadmapProgress);const path=learningPath(domains.find(d=>d.id===id)),count=path.stages.filter(s=>roadmapProgress[`${id}-${s.id}`]).length;document.getElementById('milestoneCount').textContent=`${count} of ${path.stages.length}`;document.getElementById('milestoneMeter').style.width=count/path.stages.length*100+'%';document.getElementById('stage-'+stage).classList.toggle('completed',checked);toast(checked?'Milestone complete. Your progress is saved.':'Milestone reopened.')}
function domainResourcesHTML(d){return `<div class="panel-heading"><span class="eyebrow light">THE RIGHT RESOURCE. THE RIGHT LEVEL.</span><h2>Your resource library</h2></div><label class="sr-only" for="domainResourceSearch">Search domain resources</label><input class="input" id="domainResourceSearch" type="search" placeholder="Search titles or learning topics…" value="${escapeHTML(domainResourceState.search)}" oninput="setDomainResource('search',this.value)"><div class="simple-resource-filters" aria-label="Resource filters">${[['pdf','PDF'],['video','Videos'],['course','Courses'],['udemy','Udemy'],['coursera','Coursera']].map(([value,label])=>`<button data-domain-filter="${value}" class="${domainResourceState.filter===value?'selected':''}" aria-pressed="${domainResourceState.filter===value}" onclick="setDomainResourceFilter('${value}')">${icon({pdf:'file',video:'play',course:'book',udemy:'book',coursera:'book'}[value])}<span>${label}</span></button>`).join('')}</div><p class="resource-filter-hint">Tap a filter again to show all resources.</p><p class="subtitle resource-note">Discovery links help you find courses or videos; they do not represent enrolled courses. Some platforms may require payment or sign-in. Only the downloaded study planner is available offline.</p><div id="domainResourceResults">${domainResourceResults(d)}</div>${d.id<8?`<section class="section"><div class="section-heading"><h3>Code notebook</h3><button class="text-button" onclick="copySnippet(${d.id})">Copy code</button></div><pre><code>${escapeHTML(snippet(d))}</code></pre></section>`:''}`}
function domainResourceResults(d){const state=domainResourceState,rows=getDomainResources(d).filter(r=>(state.type==='all'||r.type===state.type)&&(state.source==='all'||r.source===state.source)&&(state.level==='all'||r.level===state.level)&&r.title.toLowerCase().includes(state.search.toLowerCase()));return `<p class="result-count">${rows.length} matching resources</p>${rows.map(r=>r.generated?pdfRow(d):resourceRow(r)).join('')}${!rows.length?'<div class="empty">No resources match these filters.<button class="text-button" onclick="resetDomainResources()">Reset filters</button></div>':''}`}
function setDomainResource(key,value){domainResourceState[key]=value;main.querySelectorAll('[data-resource-key]').forEach(el=>{const active=domainResourceState[el.dataset.resourceKey]===el.dataset.resourceValue;el.classList.toggle('selected',active);el.setAttribute('aria-pressed',active)});document.getElementById('domainResourceResults').innerHTML=domainResourceResults(domains.find(d=>d.id===currentDomainId))}
function setDomainResourceFilter(filter){const selected=domainResourceState.filter===filter?'all':filter;domainResourceState={search:domainResourceState.search,type:['pdf','video','course'].includes(selected)?selected:'all',source:['udemy','coursera'].includes(selected)?selected:'all',level:'all',filter:selected};main.querySelectorAll('[data-domain-filter]').forEach(el=>{const active=el.dataset.domainFilter===selected;el.classList.toggle('selected',active);el.setAttribute('aria-pressed',active)});document.getElementById('domainResourceResults').innerHTML=domainResourceResults(domains.find(d=>d.id===currentDomainId))}
function resetDomainResources(){domainResourceState={search:'',type:'all',source:'all',level:'all',filter:'all'};renderWorkspacePanel()}
navigate('home');




